  kline.addEventListener('click',event=>{const rect=kline.getBoundingClientRect(),x=event.clientX-rect.left,y=event.clientY-rect.top,hit=[...chartAlertHits].reverse().find(item=>x>=item.x&&x<=item.x+item.w&&y>=item.y&&y<=item.y+item.h);if(hit?.type==='status'){openRule(hit.items[0].rule);return}if(hit?.type==='event'){const rule=(alerts.rules||[]).find(item=>item.id===hit.event.ruleId);if(rule)openRule(rule);return}if(hit?.items?.length){const current=Number(quote()[chartSide]);const nearest=[...hit.items].sort((a,b)=>Math.abs(a.price-current)-Math.abs(b.price-current))[0];openRule(nearest.rule)}});
  kline.addEventListener('contextmenu',event=>{event.preventDefault();const plot=kline._plot;if(!plot)return;const rect=kline.getBoundingClientRect(),localY=event.clientY-rect.top,price=plot.high-(localY-plot.pad.t)/plot.h*(plot.high-plot.low);openRule({marketCode:primaryCode,marketName:quoteName(),name:`${chartSideLabel()} ${number(price)} 快捷预警`,notifyEmail:false,notifyDesktop:true,conditions:[{side:chartSide,kind:price>=Number(quote()[chartSide])?'level_above':'level_below',threshold:Number(price.toFixed(quote().precision||3)),windowSeconds:0}]})});
function populateMarketLayoutDialog(){const quotes=(snapshot.quotes||[]).filter(x=>x.code);const options=quotes.map(x=>`<option value="${escapeHtml(x.code)}">${escapeHtml(quoteName(x))}</option>`).join('');for(const id of ['primary-market','aux-market-1','aux-market-2'])$(id).innerHTML=options;$('primary-market').value=primaryCode;$('aux-market-1').value=auxCodes[0]||quotes.find(x=>x.code!==primaryCode)?.code||'';$('aux-market-2').value=auxCodes[1]||quotes.find(x=>x.code!==primaryCode&&x.code!==$('aux-market-1').value)?.code||'';$('market-layout-error').hidden=true}
