function newsMarkup(item,index,compact=false){const title=item.title||item.content||'未命名快讯',hasBody=item.content&&item.content!==item.title,image=/^https:\/\/flash-scdn\.jin10\.com\//i.test(item.imageUrl||'')?`<img class="news-media" data-news-image="${escapeHtml(item.imageUrl)}" src="${escapeHtml(item.imageUrl)}" alt="${escapeHtml(title)}" loading="lazy" decoding="async" title="点击查看大图">`:'';return `<article class="${compact?'core-news-item':'live-news-item'} ${item.important?'important':''}" data-live-news-url="${escapeHtml(item.url||'')}" tabindex="0"><div class="news-copy"><div class="news-title-line">${item.important?'<b>重要</b>':''}${item.reportCount>1?`<b class="news-count">${item.reportCount}条报道</b>`:''}<strong>${escapeHtml(title)}</strong></div>${hasBody?`<p>${escapeHtml(item.content)}</p>`:''}${image}<div class="news-meta"><time>${timeText(item.firstPublishedAt||item.publishedAt)}${item.reportCount>1?`–${timeText(item.publishedAt)}`:''}</time><small>${escapeHtml(item.source||'金十数据')}</small></div></div></article>`}
function groupNewsItems(items){const groups=[];for(const item of items){const key=String(item.title||item.content||'').toLowerCase().replace(/[\s，。；：、,.!?！？:;（）()“”"'‘’\-]/g,'').slice(0,46),stamp=Number(item.publishedAt)||0,match=key&&groups.find(row=>row._key===key&&Math.abs(stamp-Number(row.publishedAt||0))<=30*60*1000);if(match){match.reportCount++;match.firstPublishedAt=Math.min(Number(match.firstPublishedAt)||stamp,stamp);if(String(item.content||'').length>String(match.content||'').length)match.content=item.content;match.important=match.important||item.important}else groups.push({...item,_key:key,reportCount:1,firstPublishedAt:stamp})}return groups}
function renderLiveNews(){const raw=Array.isArray(liveNews.items)?liveNews.items:[],items=groupNewsItems(raw),core=$('core-news-list');const status=liveNews.status==='connected'?'实时快讯已连接':liveNews.status==='cached'?'实时连接中断，显示本地缓存':'正在连接实时快讯';if(core){const oldTop=core.scrollTop;core.innerHTML=items.length?items.map((item,index)=>newsMarkup(item,index,true)).join(''):'<div class="intel-empty">暂时没有读取到官方快讯</div>';if(oldTop>0)core.scrollTop=oldTop;const coreStatus=$('core-news-status');if(coreStatus){coreStatus.textContent=`${status} · ${raw.length} 条${items.length<raw.length?` / ${items.length}组`:''}`;coreStatus.className=liveNews.status==='connected'?'good':liveNews.status==='cached'?'bad':''}}$('live-news-status').textContent=`${status}${liveNews.lastUpdate?` · 更新 ${timeText(liveNews.lastUpdate)}`:''} · ${raw.length} 条${items.length<raw.length?` / ${items.length}组`:''}`;$('live-news-status').className=liveNews.status==='connected'?'good':liveNews.status==='cached'?'bad':'';$('live-news-list').innerHTML=items.length?items.map((item,index)=>newsMarkup(item,index,false)).join(''):'<div class="empty-block">暂时没有读取到快讯</div>'}
async function refreshNews(){if(newsRefreshPending)return;newsRefreshPending=true;try{liveNews=await api.news(300);renderLiveNews();startupStep('news',true,liveNews.status==='connected'?'实时资讯已连接':'已载入资讯缓存')}catch(error){startupStep('news',false,'资讯连接失败，可稍后刷新');liveNews={...liveNews,status:'cached'};renderLiveNews();$('live-news-status').textContent=`快讯刷新失败 · ${userError(error)}`}finally{newsRefreshPending=false}}
$('live-news-list').onclick=handleNewsClick;$('image-fit').onclick=()=>{previewScale=1;$('image-preview').style.transform='scale(1)';$('image-preview').classList.add('fit')};$('image-reset').onclick=()=>{previewScale=1;$('image-preview').classList.remove('fit');$('image-preview').style.transform='scale(1)'};$('image-preview-stage').onwheel=e=>{e.preventDefault();previewScale=Math.min(4,Math.max(.35,previewScale*(e.deltaY<0?1.15:.87)));$('image-preview').classList.remove('fit');$('image-preview').style.transform=`scale(${previewScale})`};let imageDrag=null;$('image-preview-stage').onpointerdown=e=>{imageDrag={x:e.clientX,y:e.clientY,left:e.currentTarget.scrollLeft,top:e.currentTarget.scrollTop};e.currentTarget.setPointerCapture(e.pointerId);e.currentTarget.classList.add('dragging')};$('image-preview-stage').onpointermove=e=>{if(!imageDrag)return;e.currentTarget.scrollLeft=imageDrag.left-(e.clientX-imageDrag.x);e.currentTarget.scrollTop=imageDrag.top-(e.clientY-imageDrag.y)};$('image-preview-stage').onpointerup=e=>{imageDrag=null;e.currentTarget.classList.remove('dragging')};
