const conditionNames={level_above:'价格达到或高于',level_below:'价格达到或低于',cross_above:'向上穿越价格',cross_below:'向下穿越价格',move_up_amount:'一段时间内上涨金额',move_down_amount:'一段时间内下跌金额',move_up_percent:'一段时间内上涨比例',move_down_percent:'一段时间内下跌比例',day_up_amount:'较昨收上涨金额',day_down_amount:'较昨收下跌金额',day_up_percent:'较昨收上涨比例',day_down_percent:'较昨收下跌比例',sustained_above:'连续高于价格',sustained_below:'连续低于价格',range_enter:'进入价格区间',range_exit:'离开价格区间',spread_above:'销售与回购价差达到',drawdown_from_high:'从今日最高回落',rebound_from_low:'从今日最低反弹',volatility_amount:'一段时间内波动金额',volatility_percent:'一段时间内波动比例'};
const timedKinds=new Set(['move_up_amount','move_down_amount','move_up_percent','move_down_percent','sustained_above','sustained_below','volatility_amount','volatility_percent']);const percentKinds=new Set(['move_up_percent','move_down_percent','day_up_percent','day_down_percent','volatility_percent']);
function kindOptions(selected){const groups=[['价格位置',['level_above','level_below','cross_above','cross_below']],['时间内变化',['move_up_amount','move_down_amount','move_up_percent','move_down_percent','volatility_amount','volatility_percent']],['当日表现',['day_up_amount','day_down_amount','day_up_percent','day_down_percent','drawdown_from_high','rebound_from_low']],['持续与区间',['sustained_above','sustained_below','range_enter','range_exit','spread_above']]];return groups.map(([label,kinds])=>`<optgroup label="${label}">${kinds.map(v=>`<option value="${v}" ${v===selected?'selected':''}>${conditionNames[v]}</option>`).join('')}</optgroup>`).join('')}
function conditionCard(c,index){const percent=percentKinds.has(c.kind),timed=timedKinds.has(c.kind),range=c.kind.startsWith('range_');return `<article class="condition-card" data-index="${index}"><strong>${index+1}</strong><label>价格<select data-field="side" ${c.kind==='spread_above'?'disabled':''}><option value="ask" ${c.side!=='bid'?'selected':''}>销售价</option><option value="bid" ${c.side==='bid'?'selected':''}>回购价</option></select></label><label>监测方式<select data-field="kind">${kindOptions(c.kind)}</select></label><label>触发值<div class="unit-input"><input data-field="threshold" type="number" min="0.001" step="0.001" value="${escapeHtml(c.threshold||'')}"><select tabindex="-1" disabled><option>${percent?'%':'元/克'}</option></select></div></label><label class="range-upper ${range?'':'hidden'}">区间上限<input data-field="threshold2" type="number" step="0.001" value="${escapeHtml(c.threshold2||'')}"></label><label class="window-wrap ${timed?'':'hidden'}">观察时间<div class="unit-input"><input data-field="windowValue" type="number" min="1" value="${c.windowSeconds&&c.windowSeconds<60?c.windowSeconds:Math.max(1,(c.windowSeconds||300)/60)}"><select data-field="windowUnit"><option value="1" ${c.windowSeconds<60?'selected':''}>秒</option><option value="60" ${!c.windowSeconds||c.windowSeconds>=60?'selected':''}>分钟</option></select></div></label><button type="button" class="remove-condition" aria-label="删除条件"><i class="ph ph-trash"></i></button></article>`}
function readConditions(){return [...$('condition-list').querySelectorAll('.condition-card')].map(row=>{const kind=row.querySelector('[data-field="kind"]').value,unit=Number(row.querySelector('[data-field="windowUnit"]')?.value||60),value=Number(row.querySelector('[data-field="windowValue"]')?.value||5);return {id:ruleDraft[Number(row.dataset.index)]?.id,side:row.querySelector('[data-field="side"]').value,kind,threshold:Number(row.querySelector('[data-field="threshold"]').value),threshold2:Number(row.querySelector('[data-field="threshold2"]')?.value),windowSeconds:value*unit}})}
function describeConditionForm(c){const side=c.side==='bid'?'回购价':'销售价',value=finite(c.threshold)?Number(c.threshold).toFixed(percentKinds.has(c.kind)?2:3):'未填写',duration=c.windowSeconds<60?`${c.windowSeconds}秒`:`${c.windowSeconds/60}分钟`;let name=conditionNames[c.kind]||'监测';if(c.kind==='spread_above')return `销售与回购价差${name.replace('销售与回购价差','')} ${value}元/克`;if(c.kind.startsWith('range_'))return `${side}${name} ${value}至${number(c.threshold2)}元/克`;return `${side}${timedKinds.has(c.kind)?`在${duration}内`:''}${name} ${value}${percentKinds.has(c.kind)?'%':'元/克'}`}
function describeRuleForm(rule){const join=rule.logic==='any'?'，或者 ':rule.logic==='at_least'?`，至少满足${rule.minimumMatches}项：`:'，并且 ';return rule.conditions.map(describeConditionForm).join(join)}
function automaticRuleContent(){const conditions=readConditions(),logic=$('rule-logic').value,desc=describeRuleForm({conditions,logic,minimumMatches:Number($('rule-minimum').value)}),market=quoteName((snapshot.quotes||[]).find(x=>x.code===$('rule-market').value)||{name:$('rule-market').selectedOptions?.[0]?.textContent||'行情'}),name=`${market} · ${desc}`;return {name,subject:`【盛世预警】${name}`,message:`{规则名称}\n触发条件：{条件}\n当前价格：{当前价格}\n变化：{变化金额}\n触发时间：{触发时间}`,speech:`${market}${desc}，请查看行情。`}}
function syncAutomaticRuleContent(force=false){const form=$('rule-form'),auto=automaticRuleContent();if(force||form.dataset.manualName!=='true')$('rule-name').value=auto.name;if(force||form.dataset.manualSubject!=='true')$('rule-subject').value=auto.subject;if(force||form.dataset.manualMessage!=='true')$('rule-message').value=auto.message;if(force||form.dataset.manualSpeech!=='true')$('rule-speech-text').value=auto.speech}
