function openRule(rule=null){const dialog=$('rule-dialog'),form=$('rule-form');dialog.classList.remove('show-advanced');$('rule-advanced-toggle').textContent='高级设置';$('rule-dialog-title').textContent=rule?'编辑预警规则':'新建预警规则';form.dataset.id=rule?.id||'';form.dataset.enabled=rule?.enabled===false?'false':'true';form.dataset.manualName=rule?.name?'true':'false';form.dataset.manualSubject=rule?.emailSubject?'true':'false';form.dataset.manualMessage=rule?.messageTemplate?'true':'false';form.dataset.manualSpeech=rule?.speechText?'true':'false';const choices=(snapshot.quotes||[]).filter(x=>x.code);$('rule-market').innerHTML=choices.map(x=>`<option value="${escapeHtml(x.code)}">${escapeHtml(quoteName(x))}</option>`).join('');$('rule-market').value=rule?.marketCode||primaryCode;$('rule-reminder-mode').value=rule?.reminderMode||'rearm';$('rule-name').value=rule?.name||'';$('rule-trigger-mode').value=rule?.triggerMode||'immediate';$('rule-severity').value=rule?.severity||'normal';$('rule-logic').value=rule?.logic||'all';$('rule-minimum').value=rule?.minimumMatches||1;const cooldownUnit=Number(rule?.cooldownUnit)||60;$('cooldown-unit').value=String(cooldownUnit);$('rule-cooldown').value=rule?.cooldownSeconds!=null?rule.cooldownSeconds/cooldownUnit:30;$('rule-max').value=rule?.maxPerDay||10;$('rule-gap').value=Math.max(60,rule?.maxGapSeconds||90);$('rule-email').checked=rule?.notifyEmail!==false;$('rule-desktop').checked=rule?.notifyDesktop!==false;$('rule-sound').checked=!!rule?.notifySound;$('rule-speech').checked=!!rule?.notifySpeech;$('rule-subject').value=rule?.emailSubject||'';$('rule-message').value=rule?.messageTemplate||'';$('rule-speech-text').value=rule?.speechText||'';$('rule-sound-name').value=rule?.soundName||'chime';$('rule-sound-volume').value=rule?.soundVolume??prefs.soundVolume??180;ruleDraft=(rule?.conditions?.length?rule.conditions:[{side:'ask',kind:'move_up_amount',threshold:.1,windowSeconds:300}]).map(c=>({...c,windowSeconds:c.windowSeconds||Number(c.windowMinutes||5)*60}));$('condition-list').innerHTML=ruleDraft.map(conditionCard).join('');$('minimum-field').hidden=$('rule-logic').value!=='at_least';renderRuleRecipients(rule?.recipientIds||[]);syncAutomaticRuleContent(!rule);ruleDirty=false;dialog.showModal();updateRulePreviewOnly()}
