function renderRecipients(){$('recipient-summary').textContent=`${(mail.recipients||[]).filter(r=>r.enabled!==false).length} 位启用 · ${(mail.recipients||[]).length} 位全部`;$('recipient-list').innerHTML=(mail.recipients||[]).length?mail.recipients.map(r=>`<article class="recipient-row ${r.enabled===false?'disabled':''}" data-id="${escapeHtml(r.id)}"><label class="tiny-switch"><input data-recipient-action="toggle" type="checkbox" ${r.enabled===false?'':'checked'}><span></span></label><strong>${escapeHtml(r.name)}</strong><small>${escapeHtml(r.email)} · ${Number(r.usageCount)||0}条规则使用</small><div class="row-actions"><button data-recipient-action="edit" title="编辑"><i class="ph ph-pencil"></i></button><button data-recipient-action="delete" title="删除"><i class="ph ph-trash"></i></button></div></article>`).join(''):'<div class="empty-list"><div><strong>尚未添加收件人</strong><br><span>添加后可在每条规则中单独选择。</span></div></div>'}
function renderMail(){const c=mail.connection||{};$('mail-enabled').checked=!!mail.enabled;$('mail-running').textContent=!mail.enabled?'邮件提醒未启用':c.status==='success'?'邮件提醒已启用 · 连接正常':c.status==='failed'?'邮件已启用 · 连接失败':'邮件已启用 · 连接未验证';$('from-name').value=mail.fromName||'';$('mail-user').value=mail.user||'';$('mail-host').value=mail.host||'smtp.163.com';$('mail-port').value=String(mail.port||465);$('mail-password').value='';$('mail-password').placeholder=mail.hasPassword?'授权码已安全保存；留空不修改':'请输入邮箱授权码';$('mail-connection').textContent=c.message||'尚未测试';$('mail-connection').className=`status-chip ${c.status==='success'?'good':c.status==='failed'?'bad':''}`;renderRecipients();if(!$('rule-dialog').open)renderRuleRecipients([])}
function renderEvents(){const list=(alerts.events||[]).filter(e=>eventFilter==='all'||eventFilter==='pending'&&['pending','retrying'].includes(e.status)||eventFilter==='success'&&['success','local'].includes(e.status)||eventFilter==='failed'&&['failed','skipped'].includes(e.status));$('event-list').innerHTML=list.length?list.map(e=>`<article class="event-row ${escapeHtml(e.status)}" title="${escapeHtml((e.deliveryResults||[]).map(x=>`${x.recipient}：${x.success?'成功':x.error||'失败'}`).join('\n'))}"><i class="ph ${e.status==='success'||e.status==='local'?'ph-check-circle':e.status==='failed'?'ph-warning-circle':'ph-clock'}"></i><div><strong>${escapeHtml(e.ruleName||'预警')}</strong><span>${escapeHtml(e.description||'')}</span><small>${dateText(e.time)} · ${(e.recipients||[]).map(escapeHtml).join('、')||'本地提醒'} · ${escapeHtml(e.message||statusLabel(e.status))}</small></div><em>${statusLabel(e.status)}</em></article>`).join(''):'<div class="empty-list"><div><strong>暂无记录</strong><br><span>规则触发后会在这里显示判断和发送结果。</span></div></div>'}
function renderPrefs(){for(const [id,key] of [['mini-enabled','miniEnabled'],['mini-top','miniAlwaysOnTop'],['mini-click-through','miniClickThrough'],['mini-taskbar-mode','miniTaskbarMode'],['remember-position','rememberMiniPosition'],['start-login','startAtLogin'],['desktop-notifications','desktopNotifications'],['speech-enabled','speechEnabled'],['sound-enabled','soundEnabled'],['auto-scale','autoScale']])$(id).checked=prefs[key]!==false&&!!prefs[key];$('mini-position').value=prefs.miniPosition||'top-right';$('mini-density').value=prefs.miniDensity||'standard';$('mini-custom-text').value=prefs.miniCustomText||'盛世白银';$('ui-scale').value=Math.round((prefs.uiScale||1)*100);$('ui-scale-label').value=`${$('ui-scale').value}%`;$('mini-opacity').value=Math.max(70,Math.round((prefs.miniOpacity||.9)*100));$('mini-opacity-label').value=`${$('mini-opacity').value}%`;$('sound-name').value=prefs.soundName||'chime';$('sound-volume').value=prefs.soundVolume??180;$('sound-volume-label').value=`${$('sound-volume').value}%`;$('speech-volume').value=prefs.speechVolume??100;$('speech-volume-label').value=`${$('speech-volume').value}%`;settingsDirty=false;$('settings-dirty').hidden=true;renderMiniPreview()}
function renderMiniPreview(){const preview=$('mini-preview');if(!preview)return;preview.dataset.mode=$('mini-taskbar-mode').checked?'taskbar':$('mini-density').value;preview.style.opacity=String(Math.max(.7,Number($('mini-opacity').value||90)/100));$('mini-preview-name').textContent=$('mini-taskbar-mode').checked?'白银':$('mini-custom-text').value.trim()||'盛世白银'}
function bindSettingsTabs(){const buttons=[...document.querySelectorAll('[data-settings-view]')],groups=[...document.querySelectorAll('[data-settings-group]')],search=$('settings-search'),summary=$('settings-summary');let view='common';const show=next=>{view=next;search.value='';buttons.forEach(button=>button.classList.toggle('active',button.dataset.settingsView===view));groups.forEach(group=>group.dataset.settingsVisible=String(group.dataset.settingsGroup.split(' ').includes(view)));summary.textContent=buttons.find(button=>button.dataset.settingsView===view)?.textContent||'系统设置'};buttons.forEach(button=>button.onclick=()=>show(button.dataset.settingsView));search.oninput=()=>{const term=search.value.trim().toLowerCase();if(!term)return show(view);let count=0;buttons.forEach(button=>button.classList.remove('active'));groups.forEach(group=>{const match=group.textContent.toLowerCase().includes(term);group.dataset.settingsVisible=String(match);if(match)count++});summary.textContent=count?`找到 ${count} 个相关设置区域`:'没有找到相关设置'};show('common')}
async function renderOperationLogs(){const box=$('operation-log-list'),systemBox=$('system-log-list');if(!box)return;try{const [rows,systemRows]=await Promise.all([api.operationLogs(),api.systemLogs()]),filter=$('log-module-filter')?.value||'all',visible=filter==='all'?systemRows:systemRows.filter(row=>row.module===filter);box.innerHTML=rows.length?rows.slice(0,30).map(row=>`<article><div><strong>${escapeHtml(row.module)} · ${escapeHtml(row.action)}</strong><small>${new Date(row.time).toLocaleString('zh-CN',{hour12:false})}</small></div>${row.restoreType?`<button type="button" data-restore-operation="${escapeHtml(row.id)}">还原到修改前</button>`:''}</article>`).join(''):'<span>还没有可显示的操作记录</span>';if(systemBox)systemBox.innerHTML=visible.length?visible.slice(0,80).map(row=>`<article class="system-log ${escapeHtml(row.level)}"><div><strong>${escapeHtml(row.module)} · ${escapeHtml(row.message)}</strong><small>${new Date(row.time).toLocaleString('zh-CN',{hour12:false})}${row.count>1?` · 合并${row.count}次`:''}</small></div><span>${escapeHtml(row.level)}</span></article>`).join(''):'<span>当前筛选没有系统日志</span>'}catch(error){box.textContent=userError(error,'操作记录读取失败');if(systemBox)systemBox.textContent=userError(error,'系统日志读取失败')}}
function appSettingsPayload(overrides={}){return {...prefs,...overrides,uiScale:Number(overrides.uiScale??prefs.uiScale??1),autoScale:overrides.autoScale??prefs.autoScale??false}}
async function saveQuickScale(scale,label='显示比例'){const next=Math.min(2,Math.max(.5,Math.round(Number(scale)*100)/100));try{prefs=await api.saveAppSettings(appSettingsPayload({uiScale:next,autoScale:false}));renderPrefs();toast(`${label}已调整为 ${Math.round(next*100)}%，并已自动保存`,'good')}catch(error){toast(userError(error),'bad')}}

async function refreshStatus(){try{snapshot=await api.status();renderSnapshot();startupStep('market',true,snapshot.status==='connected'?'官方行情已连接':'行情服务已启动');if(snapshot.status==='connected'&&lastConnectionStatus!=='connected')refreshChart();lastConnectionStatus=snapshot.status}catch(error){startupStep('market',false,'行情连接失败，可稍后重连');$('connection').textContent='读取行情失败';$('connection-dot').className='status-dot error'}}async function refreshAlerts(){try{alerts=await api.alerts();renderRules();renderEvents()}catch(error){toast(error.message,'bad')}}

function confirmAction(title,message){return new Promise(resolve=>{const d=$('confirm-dialog');$('confirm-title').textContent=title;$('confirm-message').textContent=message;d.returnValue='';d.showModal();d.addEventListener('close',()=>resolve(d.returnValue==='confirm'),{once:true})})}
function openRecipient(item=null){$('recipient-dialog-title').textContent=item?'编辑收件人':'添加收件人';$('recipient-form').dataset.enabled=item?.enabled===false?'false':'true';$('recipient-id').value=item?.id||'';$('recipient-name').value=item?.name||'';$('recipient-email').value=item?.email||'';$('recipient-dialog').showModal()}
document.querySelectorAll('[data-close-dialog]').forEach(b=>b.onclick=async()=>{const d=b.closest('dialog');if(d===$('rule-dialog')&&ruleDirty&&await confirmAction('放弃未保存的修改？','关闭后，本次修改不会保存。')===false)return;d.close()});
