for(const [id,key] of [['rule-name','manualName'],['rule-subject','manualSubject'],['rule-message','manualMessage'],['rule-speech-text','manualSpeech']])$(id).addEventListener('input',()=>{$('rule-form').dataset[key]='true';ruleDirty=true});
